use serde_json::json;use hs_loop::dshtodo::TodoSession;
#[test]fn exact_replacement_counts_parallel_and_trim(){let mut s=TodoSession::default();let v=s.write(&json!({"todos":[{"content":" first ","status":"in_progress"},{"content":"second","status":"in_progress"},{"content":"done","status":"completed"}]})).unwrap();assert_eq!(v["counts"],json!({"pending":0,"inProgress":2,"completed":1}));assert_eq!(v["todos"][0]["content"],"first");assert_eq!(v.as_object().unwrap().len(),2);let v=s.write(&json!({"todos":[]})).unwrap();assert_eq!(v["todos"],json!([]));}
#[test]fn invalid_shape_and_trimmed_duplicates_do_not_change_state(){let mut s=TodoSession::default();s.write(&json!({"todos":[{"content":"one","status":"pending"}]})).unwrap();let before=s.view();for args in [json!({}),json!({"todos":[{"content":" ","status":"pending"}]}),json!({"todos":[{"content":"x","status":"bogus"}]}),json!({"todos":[{"content":"x","status":"pending","extra":1}]}),json!({"todos":[{"content":"x","status":"pending"},{"content":" x ","status":"completed"}]}),json!({"todos":[],"extra":true})]{assert!(s.write(&args).is_err());assert_eq!(s.view(),before);}}
#[test]fn reset_is_null_and_sessions_are_isolated(){let mut a=TodoSession::default();let b=TodoSession::default();assert!(a.view().is_null());a.write(&json!({"todos":[{"content":"a","status":"pending"}]})).unwrap();assert!(b.view().is_null());a.reset();assert!(a.view().is_null());}
#[test]fn history_render_is_summary_not_raw_dump(){let d=tempfile::tempdir().unwrap();let id=uuid::Uuid::new_v4();let mut w=hs_log::StreamWriter::create(d.path(),id).unwrap();w.append(hs_core::EventBuilder::new(hs_core::EventKind::ToolCall).payload(hs_core::Payload::Inline(serde_json::to_vec(&json!({"plugin":"todo_write","args":{"todos":[]},"result":{"todos":[],"counts":{"pending":0,"inProgress":0,"completed":0}}})).unwrap()))).unwrap();let r=hs_log::StreamReader::open(d.path(),id).unwrap();let a=hs_loop::assembler::assemble_messages(&r,&r.events().unwrap(),10000);assert!(a.messages.iter().any(|m|m["role"]=="tool"&&m["content"]=="Updated todo list: 0 pending, 0 in progress, 0 completed."));}
#[test]fn session_snapshot_event_and_new_turn_reset(){let d=tempfile::tempdir().unwrap();let log=tempfile::tempdir().unwrap();let cfg=d.path().join("rig");let script=d.path().join("script");std::fs::write(&script,"{\"tool\":\"todo_write\",\"args\":{\"todos\":[{\"content\":\"Do first\",\"status\":\"in_progress\"},{\"content\":\"Do parallel\",\"status\":\"in_progress\"}]}}\n").unwrap();std::fs::write(&cfg,format!("[[models]]\nname='scripted'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-scripted"))).unwrap();unsafe{std::env::set_var("HS_SEQMODEL_SCRIPT",script)}let mut s=hs_loop::repl::ReplSession::load(&cfg,log.path(),true,Some(1)).unwrap();let seen=std::sync::Arc::new(std::sync::Mutex::new(vec![]));let copy=seen.clone();s.set_ui_sink(Box::new(move|e|copy.lock().unwrap().push(e.to_json())));s.run_goal("first goal").unwrap();s.run_goal("second goal").unwrap();let events=seen.lock().unwrap();let todo=events.iter().filter(|e|e["type"]=="todo_list").collect::<Vec<_>>();assert!(todo.len()>=3);assert!(todo[0]["todos"].is_null());assert_eq!(todo[1]["todos"][0]["content"],"Do first");assert!(todo[2]["todos"].is_null());let r=hs_log::StreamReader::open(log.path(),s.stream_id()).unwrap();let mut snapshots=0;for e in r.events().unwrap(){let v:serde_json::Value=serde_json::from_slice(&r.resolve_payload(&e).unwrap()).unwrap_or_default();if v["record_type"]=="todo/write"{snapshots+=1;assert_eq!(v["todos"].as_array().unwrap().len(),2);}}assert_eq!(snapshots,2);}
